<?php require_once __DIR__.'/../config/db.php';$pdo=db();$q=trim($_GET['q']??'');if(mb_strlen($q)<2)json_response(['items'=>[]]);$like='%'.$q.'%';$s=$pdo->prepare("SELECT DISTINCT p.id,p.name,p.slug,p.image,p.image_webp,p.price,p.mrp,c.slug category_slug FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN product_synonyms ps ON ps.product_id=p.id WHERE p.is_active=1 AND (p.name LIKE ? OR p.search_terms LIKE ? OR ps.term LIKE ?) ORDER BY p.is_featured DESC,p.name LIMIT 8");$s->execute([$like,$like,$like]);$rows=$s->fetchAll();foreach($rows as &$r)$r['image']=asset_url($r['image_webp']?:$r['image']);json_response(['items'=>$rows]);